scwin.txt01_onclick = function(){
	panel2.openPanel("panel3");
}

scwin.txt02_onclick = function(){
	panel2.closePanel("panel3");
}

	scwin.checkVal1 = function() {
		return window.ck_log1 == 'panel3';
	}
	scwin.checkVal2 = function() {
		return window.ck_log2 == 'panel3';
	}	
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('panel2_panel_panel3_panelTitle_panelTitle3').click()");
		WebSquare.wUnit.addCommand("pause", "500");			
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('panel2_panel_panel3_panelTitle_panelTitle3').click()");
		WebSquare.wUnit.addCommand("pause", "500");			
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
		WebSquare.wUnit.addCommand("pause", "500");		
		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
